# loading packages that I will use for this project
library(dplyr)
library(tidyr)
library(ggplot2)
library(ggbiplot)
library(plotly)
library(uwot)
library(tidyverse)

# to set memory limit required for this script file to run, paste this into console:
## mem.maxVSize(25000) 
### sets memory limit to 25 gigabytes

# ------------------------------------------------------------------------------
# SET-UP AND DATA PROCESSING 

# reading in synthetic data: 
synthetic_data <- read.csv("synthetic_microglia_pc1_4.csv")
# coercing cluster variables to factors
synthetic_data$Morphology <- factor(synthetic_data$Morphology, levels = c("ameboid", "ramified", "rod-like", "intermediate"))
glimpse(synthetic_data)

# ------------------------------------------------------------------------------
# RUNNING UMAP 

set.seed(123)

# creating UMAP embedding 
umap_embedding_synthetic <- umap(synthetic_data, n_neighbors = 5, min_dist = 0.1, n_components = 2)

# storing the UMAP components in a dataframe 
umap_df_synthetic <- data.frame(
  UMAP1   = umap_embedding_synthetic[, 1],
  UMAP2   = umap_embedding_synthetic[, 2],
  Morphology = synthetic_data$Morphology)
head(umap_df)

# plotting UMAP using ggplot 
ggplot(umap_df_synthetic, aes(x = UMAP1, y = UMAP2, color = Morphology)) +
  geom_point(alpha = 1, size = 1) +
  scale_color_manual(values = c('ameboid' = "darkorange", 'ramified' = "cornflowerblue", 'rod-like' = "mediumslateblue", 'intermediate' = "darkgreen")) +
  theme_minimal() +
  labs(title = "UMAP Projection")+
  coord_fixed()


# ------------------------------------------------------------------------------
#PLOTTING IN PCA SPACE

# biplot that overlays PC1 and PC2
ggbiplot(synthetic_data,
         choices = c(1, 2), # specifying PCs 1 and 1
         groups = synthetic_data$Morphology,
         ellipse = TRUE,
         var.axes = TRUE,
         varname.size = 2,
         varname.adjust = 2,
         alpha = 0.4,
         repel = TRUE, 
         vector.args = list(linewidth = 0.3)) +
  scale_color_manual(values = c('ameboid' = "darkorange", 'ramified' = "cornflowerblue", 'rod-like' = "mediumslateblue", 'intermediate' = "darkgreen")) +
  scale_fill_manual(values = c('ameboid' = "darkorange", 'ramified' = "cornflowerblue", 'rod-like' = "mediumslateblue", 'intermediate' = "darkgreen")) +
  guides(shape = "none") +
  theme_minimal() +
  labs(title = "Biplot of PC2 and PC3",
       color = "Treatment", fill = "Treatment") +
  coord_fixed()


